function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'nums may contain only 0 and 1.';
  const ones = nums.reduce((a, b) => a + b, 0);
  if (!Number.isInteger(k) || k < 1 || k > ones) return 'k must be between 1 and the number of 1s in nums.';
  return null;
}

