function minMoves(nums, k) {
  const shifted = [];
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 1) {
      shifted.push(i - shifted.length);
    }
  }
  const prefix = [0];
  for (const value of shifted) {
    prefix.push(prefix[prefix.length - 1] + value);
  }

  const half = Math.floor(k / 2);
  let best = Infinity;
  for (let left = 0; left + k <= shifted.length; left++) {
    const mid = left + half;
    const right = left + k;
    const median = shifted[mid];
    const below = median * (mid - left) - (prefix[mid] - prefix[left]);
    const above = (prefix[right] - prefix[mid + 1]) - median * (right - mid - 1);
    best = Math.min(best, below + above);
  }
  return best;
}

