function minMoves(nums, k) {
  // Breadth-first search over every arrangement reachable by adjacent swaps (bitmask states).
  const n = nums.length;
  let start = 0;
  for (let i = 0; i < n; i++) if (nums[i] === 1) start |= 1 << i;
  const run = (1 << k) - 1;
  const done = mask => { for (let s = 0; s + k <= n; s++) if (((mask >> s) & run) === run) return true; return false; };
  const dist = new Map([[start, 0]]);
  const queue = [start];
  for (let q = 0; q < queue.length; q++) {
    const mask = queue[q];
    if (done(mask)) return dist.get(mask);
    for (let i = 0; i + 1 < n; i++) {
      const a = (mask >> i) & 1, b = (mask >> (i + 1)) & 1;
      if (a === b) continue;
      const next = mask ^ (3 << i);
      if (!dist.has(next)) { dist.set(next, dist.get(mask) + 1); queue.push(next); }
    }
  }
  return -1;
}

