function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const density = 0.05 + rand() * 0.9;
  const nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  if (!nums.includes(1)) nums[Math.floor(rand() * n)] = 1;
  const ones = nums.reduce((a, b) => a + b, 0);
  const pick = rand();
  const k = pick < 0.15 ? ones : pick < 0.25 ? 1 : 1 + Math.floor(rand() * ones);
  return [nums, k];
}
